  VALUES 
    (52::BIGINT, 'Las clases suelen ser cortas pero tiene que leer y hacer los resumenes que el pide para poder entender el curso, preparese para hacer quices cada 15 días pero en si el profe es muy buena persona y muy buen profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '3d4cf2ef5584fcb6565dd5144bc3afa982eec4540f22d3007cb857b744e0d2b2'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'El curo no es para nada fácil como lo fue micro! El profe explica bien pero HAY que tomar notas en clase porque con solo el libro no basta. Muy buena gente pero tiene riña con Chat GPT jajaja. Es un amor de persona.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-12T00:00:00+00:00'::TIMESTAMPTZ, '32ed8e21f00fe18ad9c3c924f46903a5e04184c356f79c2c67635114bb77aa47'::TEXT, ARRAY[2396]::BIGINT[]),
    (52::BIGINT, 'La verdad es que el profe es tan estructurado y ordenado que lo hace mil veces más sencillo, ojalá todos los profes fueran como él, si recomiendo repasar y estudiar bastante, poner atención en clase y hacer apuntes. Pero considero que si le pone con el curso pasa fácil, tampoco es desgastante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, 'a124a29475da8b09000eee5ee1cf8924c7e6034a4ce2ed1cbdd113bbcf77f7e6'::TEXT, ARRAY[2396]::BIGINT[]),
    (52::BIGINT, 'Las clases son cortas y explica muy bien. Los exámenes, el proyecto y las tareas son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a923e70c38a7cad5339fb010f8741f6ce85ee7f6a858f71f91357f6a5a2d81b5'::TEXT, ARRAY[2396]::BIGINT[]),
    (52::BIGINT, 'Pocas tareas, conoce mucho del tema y las clases son rápidas, hay que leer un poco del libro, los exámenes son muy fáciles y califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'dc5c6315995222c546a70c49bbe4f453f6f43aade9500be41b5fb0949c3c35b9'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Los examenes son faciles, explica super bien, si se pone atencion y se estudia, se pasa facil. Los trabajos son bastante faciles y no consumen tanto tiempo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '69ce44a8558c0cc14c2fa644a45c7daca65c0f4ea9eeb16b2158c0d1c4607534'::TEXT, ARRAY[2396]::BIGINT[]),
    (52::BIGINT, 'Muy buen profesor, tiene que poner de su parte y estudiar los capítulos de los libros para que vaya bien a las clases y no se pierda. Da mucha ayuda a los estudiantes y se preocupa porque usted aprenda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd16cc952ccb063efe035e0709eb70ae47fb4c81534614d4cb4f776fbeb870705'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a573a1b5926cf6e493b977778615da5040554213f91524dd111f2c4cc39789fe'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Es un buen profe. Se nota que sabe mucho de la materia, sin embargo, el curso se apoya y basa, principalmente, en el libro. Las clases son mas que todo para reforzar. Tareas fáciles, al igual que el proyecto.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'afdded97bab619a46bacab9519cf269cd041bb1117b7c7e75306ba83932508e6'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Hace que el curso sean sencillo, califica bien, los exámenes son sencillos, solamente las clases son aburridas y las hace muy rápidas, él supone que con leer el libro uno aprenderá.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '09b4c54362ccc373f4843976c9830da4fe80dcf13bf9e310059e921fd089655b'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchos proyectos grupales']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '91ca3306c692f2965b2f2dc86dea3d39a2886ec374fcb4f65ecc414a55f98219'::TEXT, ARRAY[2442]::BIGINT[]),
    (52::BIGINT, 'Muy buen profe, explica con mucha paciencia y deja todo muy claro. Se debe poner mucha atención a las clases y hacer los debidos apuntes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9133fd1fef09ff4a3afd329233e1f6c0f8232af7924f1ec62b87881f81fe9171'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Buen profe, las clases suelen ser cortas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd625cd79b934915b3d7350495b2705b53fa7379e8a9c5692121df7a361d105e4'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, 'cb269c773fd9de8d3a78097d61ce6478459d78927ac1264a6e9f7ddd6e78ea9d'::TEXT, ARRAY[2442]::BIGINT[]),
    (52::BIGINT, 'Es muy buen profesor, le encanta lo que hace, lo motiva a uno a aprender de la materia, proporciona mucho material de apoyo, los trabajos individuales y grupales en general enseñan mucho. Los quices solo hace falta prepararse con lecturas o videos, y los examenes son muy prácticos y sencillos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'ada839d96c1651b3b679aedb2a14cf0ca219b20957dd031d63015ac9103771de'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Es muy buen profesor y explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '9d0bf2e34c317ba0167452c970a4f69859dd098f32a34a2e11ee8de0b277645d'::TEXT, ARRAY[2442]::BIGINT[]),
    (52::BIGINT, 'Al profesor le encanta lo que hace, los exámenes no son difíciles, busquen exámenes viejos, hay que leer los capítulos que se van a ver en clase porque él asume que uno tiene conocimiento del tema.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'd5f86e70a600d54a865fd3246df87e37afe51b2aa11be3bb13822d1242e36618'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'El mae sabe muchísimo de la materia, se nota que le encanta lo que hace. No hace quizes y los exámenes no son difíciles, es solo practicar y ojalá buscar exámenes viejos. Si hay que leer los capítulos que se van a ver en clase porque él asume que uno tiene conocimiento del tema. Lo recomiendo:)'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2019-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b9e992c8adc8f1e61cfc12b0087e67cece362bc17d318e5d8a1012f745c85fe8'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Los quices son muy textuales, pero los exámenes son prácticos y ayuda mucho para practicar los temas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '7ec54368965a30e1e485f57dbbc8fcbee495cd4d4e88e6950508b5e30120f98c'::TEXT, ARRAY[2442]::BIGINT[]),
    (52::BIGINT, 'Es de los mejores profesores de la Escuela. Muy atento y paciente, siempre ayuda a los estudiantes en lo que necesiten. Los exámenes no son difíciles pero sí hay que practicar bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-25T00:00:00+00:00'::TIMESTAMPTZ, '0ea64aaa3a9bb0a84bc789e37ecdbb3ed9968ee3b6c1875aa5fb99fa845ab5be'::TEXT, ARRAY[2396]::BIGINT[]),
    (52::BIGINT, 'Atiende dudas, tiene mucha paciencia, se nota que le gusta lo que hace, califica suave. Solamente hay que leerse leídos los capítulos antes de la clase para entender mejor'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '88083ebc70e69b1ec66c232011795c9288943a65b5286e3f9b961e1602c6c6ca'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Buen profe, sabe bastante sin embargo si no te lees los capítulos que se van a ver en la clase no vas a entender nada, los quices son algo un poquillo rudos pero se pueden hacer, los exámenes son muy fáciles.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '37d3789d6951ea7e4ab33b03ebd169ff7d04d13ca62bb017837fab58a2cc937b'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Excelente profesor. Se aprende bastante. Los quices son un poquito difíciles (nada de otro mundo), pero los exámenes sí son muy fáciles :)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7bfbfe60d6dfd1df9615e452f4d89294331a4aabb0a9dadc4a5529a34c596452'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'Es un buen profesor aunque las clases se tornan aburridas y un poco confusas, los exámenes son fáciles.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '28f9c732cb17cf139a5275ceaa8a8439a5bae49ad58fc9cf62ad794c51e71200'::TEXT, ARRAY[2371]::BIGINT[]),
    (52::BIGINT, 'El profe es excelente, muy organizado e intenta hacer mucha práctica para el examen. Solamente tiene que leerse cada capítulo antes porque el profe da la clase asumiento que usted lo hizo y tiene un poco de conocimiento sobre el tema, si no estudia los capítulos antes, pasará toda la clase perdido.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-21T00:00:00+00:00'::TIMESTAMPTZ, '5e5741be5a41e6444bf4e216023468a6cda72860a375a021fdb5f333e0729348'::TEXT, ARRAY[2396]::BIGINT[]),
